    message = 0;
    return;
  }

  static mono instance = create_mono();

  string password;
  int length = message;

  if (length < 8 || length > 16)
  {
    return;
  }

  string random_chars(8);
  for (int i = 0; i < 8; i++)
  {
    random_chars[i] = generate_random_char(9);
  }

  password = random_chars;

  if (message < 8 || message > 16)
  {
    return;
  }

  *data = password;

  return message;
}

